-- Bargello 122 blog v3: La Vie Est Belle metinden çıkarıldı, SSS cevabı düzeltildi
update blog_posts set
  content = replace(replace(content, $a$<p><strong>Bargello 122, Hugo Boss Boss Intense'in muadilidir.</strong> İncelediğimiz bağımsız kod listelerinin hepsi bu eşleşmeyi veriyor. Bazı satış sayfalarında La Vie Est Belle'e benzetiliyor, ancak notalar Boss Intense'i gösteriyor: Bargello'nun 122 için verdiği altı notanın beşi (vanilya, gül, sandal ağacı, amber, paçuli) Boss Intense'te de var, yalnızca üstteki portakal çiçeği yok. Boss Intense ayrıca baharatlar, kumkuat, yasemin, benzoin ve misk içeriyor; bunlar 122'nin tarifinde geçmiyor. La Vie Est Belle ile ortak nota ise üç: portakal çiçeği, vanilya ve paçuli. La Vie Est Belle'in armut, frenk üzümü, iris, pralin ve tonka notaları 122'de yok.</p>$a$, $b$<p><strong>Bargello 122, Hugo Boss Boss Intense'in muadilidir.</strong> İncelediğimiz bağımsız kod listelerinin hepsi bu eşleşmeyi veriyor. Bargello'nun 122 için verdiği altı notadan beşi Boss Intense'te de bulunur: vanilya, gül, sandal ağacı, amber ve paçuli. Aradaki fark açılışta: 122 portakal çiçeğiyle açılır, bu nota Boss Intense'te yok. Boss Intense'te ise baharatlar, kumkuat, yasemin, benzoin ve misk var; bunlar 122'nin notaları arasında geçmiyor.</p>$b$), $c$<p>Bargello 122, Hugo Boss Boss Intense'in muadilidir. Bargello'nun 122 için verdiği altı notanın beşi Boss Intense'te de var; La Vie Est Belle ile ortak nota sayısı ise üç.</p>$c$, $d$<p>Bargello 122, Hugo Boss Boss Intense'in muadilidir. Bargello'nun 122 için verdiği altı notadan beşi (vanilya, gül, sandal ağacı, amber ve paçuli) Boss Intense'te de bulunur.</p>$d$),
  updated_at = now()
where id = '46dea4c1-17bc-446f-8609-5f24d02f2863'
  and position($a$<p><strong>Bargello 122, Hugo Boss Boss Intense'in muadilidir.</strong> İncelediğimiz bağımsız kod listelerinin hepsi bu eşleşmeyi veriyor. Bazı satış sayfalarında La Vie Est Belle'e benzetiliyor, ancak notalar Boss Intense'i gösteriyor: Bargello'nun 122 için verdiği altı notanın beşi (vanilya, gül, sandal ağacı, amber, paçuli) Boss Intense'te de var, yalnızca üstteki portakal çiçeği yok. Boss Intense ayrıca baharatlar, kumkuat, yasemin, benzoin ve misk içeriyor; bunlar 122'nin tarifinde geçmiyor. La Vie Est Belle ile ortak nota ise üç: portakal çiçeği, vanilya ve paçuli. La Vie Est Belle'in armut, frenk üzümü, iris, pralin ve tonka notaları 122'de yok.</p>$a$ in content) > 0
  and position($c$<p>Bargello 122, Hugo Boss Boss Intense'in muadilidir. Bargello'nun 122 için verdiği altı notanın beşi Boss Intense'te de var; La Vie Est Belle ile ortak nota sayısı ise üç.</p>$c$ in content) > 0
returning id, position('La Vie' in content) as la_vie_kaldi_mi;
